    33	    d["depends_on"] = [e.target for e in g.successors(nid, hard=True)]
    34	    d["depended_on_by"] = [e.source for e in g.predecessors(nid, hard=True)]
    35	    d["ancestors"] = g.ancestors(nid)
    36	    for kind in ATTACHMENT_KINDS:
    37	        d[kind + "s"] = [node_json(a) for a in g.attachments(nid, kind)]
